"""Rebuild browser study examples from tested Python engines, without external services."""
import json
from pathlib import Path

from helioforge.studies import StudyRequest, catalogue, evaluate

root = Path(__file__).resolve().parents[1]
studies = catalogue()
bundle = {"catalogue": studies, "results": {s["id"]: evaluate(StudyRequest(study=s["id"])) for s in studies}}
encoded = json.dumps(bundle, ensure_ascii=True, separators=(",", ":"), allow_nan=False)
(root / "apps/web/src/roadmap-data.ts").write_text(
    "// Generated by scripts/generate-studies.py; edit Python models instead.\n"
    "namespace HF { export const STUDY_BUNDLE: StudyBundle = " + encoded + "; }\n", encoding="utf-8", newline="\n")
print(json.dumps({"studies": len(studies), "bytes": len(encoded.encode())}))
